// RUST UP OFFLINE simulation: verified sample Stars order -> separate DEMO balance.
// This is not a Worker module and must never be deployed or fed real receipts.
// It explicitly forbids real-money operation and never touches game accounts.
import {simulateDeposit} from './ledger.mjs';
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[89ab][0-9a-f]{3}-[89ab][0-9a-f]{12}$/i;
// Accept standard RFC4122 UUIDs generated by crypto.randomUUID.
const ID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
function localOnly(){
 if(process.env.NODE_ENV==='production'||
    process.env.LOCAL_PAYMENTS_TEST_ONLY!=='1'||
    process.env.RUSTUP_REAL_PAYMENTS_DISABLED!=='true')
  throw Error('demo_settlement_must_never_run_with_live_payments');
}
export function inspectSimulatedStarsOrder(order){
 localOnly();
 if(!order||typeof order!=='object'||!ID.test(order.id||'')||
  !Number.isSafeInteger(order.telegram_user_id)||order.telegram_user_id<=0||
  order.status!=='paid'||!Number.isSafeInteger(order.requested_amount_minor)||
  order.requested_amount_minor<100||order.requested_amount_minor>1000000||
  !Number.isSafeInteger(order.price_stars)||order.price_stars<=0||
  !Number.isSafeInteger(order.paid_at_ms)||order.paid_at_ms<=0||
  typeof order.telegram_charge_id!=='string'||
  !/^demo-only:[A-Za-z0-9_-]{8,100}$/.test(order.telegram_charge_id)||
  typeof order.invoice_url!=='string'||
  !/^https:\/\/t\.me\/\$demo-[A-Za-z0-9_-]+$/.test(order.invoice_url))
  throw Error('paid_simulation_order_not_verified');
 return Object.freeze({
  userId:order.telegram_user_id,
  reference:'demo:stars:'+order.id,
  units:order.requested_amount_minor,
  simulationOnly:true,withdrawable:false,gameStakesAllowed:false
 });
}
export async function applySimulatedStarsOrder(starsDb,demoDb,orderId){
 localOnly();
 if(!ID.test(orderId||'')||!starsDb?.prepare||!demoDb?.batch)
  throw Error('invalid_demo_settlement_parameters');
 const row=await starsDb.prepare(
  'SELECT id,telegram_user_id,requested_amount_minor,price_stars,status,'+
  'telegram_charge_id,invoice_url,paid_at_ms '+
  'FROM rustup_stars_variable_orders WHERE id=?'
 ).bind(orderId).first();
 const event=inspectSimulatedStarsOrder(row);
 const receipt=await simulateDeposit(demoDb,{
  userId:event.userId,channel:'stars',
  reference:event.reference,units:event.units
 });
 return {...receipt,simulationOnly:true,realMoneyAccepted:false,
  gameStakesAllowed:false,withdrawable:false};
}
